  // Fetch from DB with parameterized queries, never inline
  return db.query('SELECT id, name, email FROM users');
}

// app.js
const { getUsers } = require('./services/userService');
app.get('/users', authenticate, async (req, res, next) => {
  try {
    const users = await getUsers();
    res.json(users);
  } catch (err) {
    next(err); // see error handling section
  }
});
```

