## ✅ Recommended Corrected `app.js`

Here is a hardened version incorporating all fixes:

```js
'use strict';

const express   = require('express');
const helmet    = require('helmet');
const cors      = require('cors');
const rateLimit = require('express-rate-limit');
const morgan    = require('morgan');

const app = express();

// ── Security headers ────────────────────────────────────────────
app.use(helmet());
app.disable('x-powered-by');

// ── CORS ────────────────────────────────────────────────────────
app.use(cors({
  origin: process.env.ALLOWED_ORIGIN,
  methods: ['GET'],
  allowedHeaders: ['Content-Type', 'x-api-key'],
}));

// ── Rate limiting ───────────────────────────────────────────────
app.use(rateLimit({ windowMs: 15 * 60 * 1000, max: 100 }));

// ── Request logging ─────────────────────────────────────────────
app.use(morgan('combined'));

// ── Body parsing ─────────────────────────────────────────────────
app.use(express.json({ limit: '10kb' })); // Prevent large payload DoS

// ── Auth middleware ──────────────────────────────────────────────
const authenticate = (req, res, next) => {
  const key = req.headers['x-api-key'];
  if (!key || key !== process.env.API_KEY) {
    return res.status(401).json({ error: 'Unauthorized' });
  }
  next();
};

// ── Routes ───────────────────────────────────────────────────────
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', authenticate, async (req, res, next) => {
  try {
    // Replace with real parameterized DB query
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob',   email: 'bob@example.com'   },
    ];
    res.json(users);
  } catch (err) {
    next(err);
  }
});

// ── Global error handler ─────────────────────────────────────────
app.use((err, req, res, _next) => {
  console.error(err);
  res.status(err.statusCode || 500).json({
    error: process.env.NODE_ENV === 'production'
      ? 'Internal server error'
      : err.message,
  });
});

// ── Start ────────────────────────────────────────────────────────
const PORT = process.env.PORT || 3000;
app.listen(PORT, '127.0.0.1', () => {
  console.log(`Server running on 127.0.0.1:${PORT}`);
});

module.exports = app;
```

